create table if not exists public.place_import_sources (id uuid primary key default gen_random_uuid(),place_id uuid not null references public.places(id) on delete cascade,source_url text not null check (char_length(source_url)<=2000),source_kind text not null check (source_kind in ('website','facebook')),imported_fields jsonb not null default '{}'::jsonb,rights_confirmed boolean not null default false,confirmed_by uuid references auth.users(id) on delete set null,confirmed_at timestamptz,created_at timestamptz not null default now());
create index if not exists place_import_sources_place_idx on public.place_import_sources(place_id,created_at desc);
alter table public.place_import_sources enable row level security;
create policy "Business editors manage import sources" on public.place_import_sources for all to authenticated using (exists(select 1 from public.places p where p.id=place_id and public.is_business_editor(p.business_id))) with check (exists(select 1 from public.places p where p.id=place_id and public.is_business_editor(p.business_id)));
create policy "Admins read import sources" on public.place_import_sources for select to authenticated using (public.is_geppao_admin());
create or replace function public.create_my_business(requested_name text,requested_phone text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare actor uuid:=auth.uid();existing record;created public.businesses;begin if actor is null then raise exception 'Authentication required';end if;if char_length(btrim(coalesce(requested_name,'')))<2 or char_length(requested_name)>120 then raise exception 'Business name is invalid';end if;select b.id,b.name,b.status into existing from public.business_members bm join public.businesses b on b.id=bm.business_id where bm.user_id=actor and bm.role in ('owner','admin','editor') limit 1;if existing.id is not null then return jsonb_build_object('id',existing.id,'name',existing.name,'status',existing.status,'existing',true);end if;insert into public.businesses(owner_user_id,name,phone,email,status,verification_status) select actor,btrim(requested_name),nullif(btrim(requested_phone),''),u.email,'active','unverified' from auth.users u where u.id=actor returning * into created;insert into public.business_members(business_id,user_id,role) values(created.id,actor,'owner');return jsonb_build_object('id',created.id,'name',created.name,'status',created.status,'existing',false);end;$$;
revoke all on function public.create_my_business(text,text) from public;grant execute on function public.create_my_business(text,text) to authenticated;
